package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.server.level.*;import net.minecraft.world.entity.Entity;import net.minecraft.world.item.ItemStack;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.Vec3;import java.util.*;
/** Monitor is bound to the immutable load token, never just a bay number. */
public final class Ndc01Monitor {
 public static void clear(ItemStack s){var n=PlatformMonitor.tag(s);for(String k:new String[]{"NdcCarrier","NdcLoad","NdcSlot","NdcReturnPosition","NdcDimension"})n.remove(k);PlatformMonitor.save(s,n);}
 public static void bind(ServerPlayer p,Ndc01Entity c,int slot){selectBay(p,c,slot,true); } public static void selectBay(ServerPlayer p,Ndc01Entity c,int slot,boolean notify){var s=p.getMainHandItem();if(!SbwCompat.isMonitor(s)||!c.canUse(p)||c.loadId(slot)==null)return;var home=CarrierFleet.home(s);if(home!=null&&!home.equals(c.getUUID())){CarrierFleet.message(p,"Monitor belongs to another carrier. Link this carrier explicitly first.");return;}var feedback=notify?MonitorLinkFeedback.begin(p):null;CarrierFleet.bind(p,c);var n=PlatformMonitor.tag(s);n.remove("PadLoad");n.putUUID("NdcCarrier",c.getUUID());n.putUUID("NdcLoad",c.loadId(slot));n.putInt("NdcSlot",slot);n.putLong("NdcReturnPosition",c.blockPosition().asLong());n.putString("NdcDimension",c.level().dimension().location().toString());PlatformMonitor.save(s,n);if(notify)p.displayClientMessage(Component.literal("NDC-01 bay "+(slot+1)+" linked. Ship link retained. C launches this bay; Shift + C returns to carrier."),true);if(notify)MonitorLinkFeedback.finish(p,feedback);}
 public static boolean ready(ServerPlayer p,Ndc01Entity c,int slot){if(p==null||!p.isAlive()||p.hasDisconnected()||p.level()!=c.level()||!c.permitted(p)||p.distanceToSqr(c)>Math.pow(AddonConfig.droneMaxRange(),2)||InjuryServer.cannotOperate(p))return false;var s=p.getMainHandItem();var n=PlatformMonitor.tag(s);return SbwCompat.isMonitor(s)&&n.hasUUID("NdcCarrier")&&c.getUUID().equals(n.getUUID("NdcCarrier"))&&n.hasUUID("NdcLoad")&&n.getUUID("NdcLoad").equals(c.loadId(slot))&&n.getInt("NdcSlot")==slot&&n.getString("NdcDimension").equals(c.level().dimension().location().toString());}
 public static boolean pendingMatches(ServerPlayer p,Ndc01Entity c,UUID load){if(p==null||load==null||!p.isAlive()||p.isSpectator()||p.hasDisconnected()||p.level()!=c.level()||!c.permitted(p)||p.distanceToSqr(c)>Math.pow(AddonConfig.droneMaxRange(),2)||InjuryServer.cannotOperate(p)||!SbwCompat.hasEquippedFpvGoggles(p))return false;var n=PlatformMonitor.tag(p.getMainHandItem());return SbwCompat.isMonitor(p.getMainHandItem())&&n.hasUUID("NdcCarrier")&&c.getUUID().equals(n.getUUID("NdcCarrier"))&&n.hasUUID("NdcLoad")&&load.equals(n.getUUID("NdcLoad"))&&n.getInt("NdcSlot")==c.bay();}
 public static boolean request(ServerPlayer p){return request(p,false);}
 public static boolean request(ServerPlayer p,boolean returnToCarrier){var s=p.getMainHandItem();var n=PlatformMonitor.tag(s);if(!SbwCompat.isMonitor(s)||!n.hasUUID("NdcCarrier"))return false;if(!n.getString("NdcDimension").equals(p.level().dimension().location().toString())){PlatformMonitor.message(p,"NDC-01 is in another dimension.");return true;}var entity=p.serverLevel().getEntity(n.getUUID("NdcCarrier"));if(returnToCarrier||p.isShiftKeyDown()){if(CarrierFleet.home(s)!=null){CarrierFleet.request(p,CarrierFleet.home(s));return true;}if(entity instanceof Ndc01Entity c&&c.permitted(p)||entity==null&&n.contains("NdcReturnPosition")){var previous=SbwCompat.findLinkedDrone(p,s);if(previous!=null)SbwCompat.resetDroneInput(previous);Id01Sessions.stop(p);VatagSessions.stop(p);n=PlatformMonitor.tag(s);n.putBoolean(SbwCompat.TAG_USING,false);n.remove("NdcLoad");PlatformMonitor.save(s,n);VatagMonitorTag.link(s,n.getUUID("NdcCarrier"),entity==null?net.minecraft.core.BlockPos.of(n.getLong("NdcReturnPosition")):entity.blockPosition(),n.getString("NdcDimension"));Wd01Entity.markMonitor(s,true);VatagSessions.start(p,n.getUUID("NdcCarrier"));}else PlatformMonitor.message(p,"Carrier is unavailable. Link again at its current position.");return true;}
  if(n.hasUUID("NdcLoad")){if(!(entity instanceof Ndc01Entity c)){PlatformMonitor.message(p,"Linked carrier is not loaded or was removed.");return true;}int slot=n.getInt("NdcSlot");if(c.busy()&&slot==c.bay())return true;if(!ready(p,c,slot)){PlatformMonitor.message(p,"Bay link expired: cargo was unloaded or replaced. Link the selected bay again.");return true;}c.request(p,slot,n.getUUID("NdcLoad"),c.selectedTarget,false);return true;}
  if(CarrierFleet.home(s)!=null){var target=SbwCompat.getLinkedDroneUuid(s);CarrierFleet.request(p,target==null?CarrierFleet.home(s):target);return true;}var flying=SbwCompat.findLinkedDrone(p,s);if(flying!=null){if(flying instanceof Id01Entity d)Id01Sessions.start(p,d.getUUID());else if(!SbwCompat.isUsingLinkedMonitor(s))s.getItem().use(p.level(),p,net.minecraft.world.InteractionHand.MAIN_HAND);}return true;
 }
 public static void launched(ServerPlayer p,Ndc01Entity c,Entity drone){if(p==null)return;var monitor=p.getMainHandItem();if(!SbwCompat.isMonitor(monitor))return;var n=PlatformMonitor.tag(monitor);n.remove("NdcLoad");PlatformMonitor.save(monitor,n);CarrierFleet.launched(p,c,drone);}

 public static void departure(Entity drone,Ndc01Entity c){drone.getPersistentData().putUUID("NdcLaunchParent",c.getUUID());drone.getPersistentData().putDouble("NdcClearY",c.anchor(c.bay()).y+1.65);drone.getPersistentData().putLong("NdcLaunchUntil",c.level().getGameTime()+40);}
 public static boolean grace(Entity a,Entity b){if(a==null||!(b instanceof Ndc01Entity))return false;var n=a.getPersistentData();return n.hasUUID("NdcLaunchParent")&&b.getUUID().equals(n.getUUID("NdcLaunchParent"))&&a.level().getGameTime()<=n.getLong("NdcLaunchUntil");}
 /** Only excludes the conservative below-body water probe while emerging through the sealed bay. Actual fluid contact is always handled first. */
 public static boolean containedLaunch(Entity e){var n=e.getPersistentData();if(!n.hasUUID("NdcLaunchParent")||e.level().getGameTime()>n.getLong("NdcLaunchUntil")||!(e.level()instanceof ServerLevel l)||!(l.getEntity(n.getUUID("NdcLaunchParent"))instanceof Ndc01Entity c)||!c.isAlive()||c.isWreck()||!c.floating()||c.bay()<0||c.bay()>=18)return false;var d=e.position().subtract(c.anchor(c.bay()));return d.y>=-.1&&d.y<=1.7&&d.horizontalDistanceSqr()<=1.44;}
 public static void departureInput(Entity e){var n=e.getPersistentData();if(!n.hasUUID("NdcLaunchParent"))return;if(e.level().getGameTime()>n.getLong("NdcLaunchUntil")){n.remove("NdcLaunchParent");n.remove("NdcLaunchUntil");n.remove("NdcClearY");return;}if(e instanceof CubedFpvDroneEntity d&&n.getLong("NdcLaunchUntil")-e.level().getGameTime()>=10&&e.getY()<n.getDouble("NdcClearY")){d.setUpInputDown(true);d.setDownInputDown(false);d.setOnGround(false);var v=d.getDeltaMovement();d.setDeltaMovement(v.x,Math.max(.18,v.y),v.z);}}
 private Ndc01Monitor(){}
}
